const input = $input.first().json;

const clamp = (value, min, max) => Math.min(max, Math.max(min, Number(value) || 0));
const clarity = clamp(input.outcome_clarity, 1, 5);
const systems = clamp(input.systems_touched, 1, 6);
const external = clamp(input.external_services, 0, 8);
const unknowns = clamp(input.unanswered_questions, 0, 6);
const sensitive = clamp(input.sensitive_data_level, 0, 3);
const revisions = clamp(input.revision_rounds, 1, 5);
const rush = input.rush_delivery === true;

const fitScore = Math.round((clarity / 5) * 55 + Math.max(0, 25 - unknowns * 5) + Math.max(0, 20 - sensitive * 5));
const riskScore = Math.min(40, Math.round((5 - clarity) * 3 + (systems - 1) * 2 + external * 2 + unknowns * 3 + sensitive * 4 + (revisions - 1) * 2 + (rush ? 5 : 0)));

let recommendation = 'Fixed-scope proposal';
let nextStep = 'Confirm the stated output, timeline, and acceptance criteria before quoting.';
let priceCushion = '0–10%';

if (riskScore >= 24 || clarity <= 2 || unknowns >= 4) {
  recommendation = 'Paid discovery first';
  nextStep = 'Resolve the unanswered questions and document the source, output, failure behavior, and change boundary before pricing the build.';
  priceCushion = '25–40% after discovery';
} else if (riskScore >= 14) {
  recommendation = 'Phased proposal';
  nextStep = 'Quote a small validation milestone first, then price the remaining build from observed data.';
  priceCushion = '15–25%';
}

const questions = [];
if (clarity < 4) questions.push('What exact output proves the automation worked?');
if (systems > 2) questions.push('Which system owns the source of truth?');
if (external > 0) questions.push('What should happen when an outside service times out or returns partial data?');
if (unknowns > 0) questions.push('Which assumptions still need a sample, API response, or owner decision?');
if (sensitive > 0) questions.push('Can the first test use redacted or non-production data?');
if (revisions > 2) questions.push('Which changes require a new estimate instead of another revision?');

return [{
  json: {
    lead_label: String(input.lead_label || 'Unlabeled lead'),
    fit_score: Math.min(100, Math.max(0, fitScore)),
    delivery_risk_score: riskScore,
    recommendation,
    price_cushion: priceCushion,
    next_step: nextStep,
    questions_to_ask: questions.length ? questions : ['Confirm the deadline and final approval owner.'],
    explanation: `Risk reflects ${systems} system(s), ${external} outside service(s), ${unknowns} unanswered question(s), and sensitive-data level ${sensitive}.`
  }
}];
